// Node must produce exactly what the Python package produces on the shared synthetic fixtures.
// Goldens are generated by Python: python -c "..." (see js/parity/README).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { convert } from '../dist/index.js';

const FX = new URL('../../tests/fixtures/', import.meta.url);
const GOLD = new URL('./golden/', import.meta.url);
for (const f of readdirSync(FX).filter((f) => f.endsWith('.html'))) {
  test(`matches Python on ${f}`, () => {
    const md = convert(readFileSync(new URL(f, FX), 'utf8'), 'https://fixture.example/', { links: true });
    assert.equal(md, readFileSync(new URL(f.replace('.html', '.md'), GOLD), 'utf8'));
  });
}
